int n;
int a[105];
const int Mod=1'000'000'007;

int ksmii(int a,int b){
	if(!b){
		return 1;
	}
	int ff=ksmii(a,b>>1);
	ff=1LL*ff*ff%Mod;
	if(b&1){
		ff=1LL*ff*a%Mod;
	}
	return ff;
}

pair<int,int> solve(int l,int r,int lim){
	int minx=Mod,cnt;
	for(int i=l;i<=r;i++){
		if(a[i]<minx){
			minx=a[i];
			cnt=1;
		}else if(a[i]==minx){
			cnt++;
		}
	}
	if(cnt==r-l+1){
		return make_pair((ksmii(2,r-l+1)-2+Mod)%Mod,ksmii(2,minx-lim-1));
	}
	pair<int,int> ans;
	int L=-1,rem=r-l+1;
	int x1=1,x2=1;
	for(int i=l;i<=r+1;i++){
		if(L==-1&&a[i]>minx){
			L=i;
		}else if(L!=-1&&a[i]<=minx){
			rem-=i-L;
			pair<int,int> tmp=solve(L,i-1,minx);
			x1=1LL*x1*(tmp.first+4LL*tmp.second%Mod)%Mod;
			x2=2LL*x2*tmp.second%Mod;
			L=-1;
		}
	}
	x1=(x1-x2+Mod)%Mod;
	ans.first=((1LL*x1*ksmii(2,rem)%Mod)+(1LL*x2*((ksmii(2,rem)-2+Mod)%Mod)%Mod))%Mod;
	ans.second=1LL*x2*ksmii(2,minx-lim-1)%Mod;
	return ans;
}

int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++){
		scanf("%d",a+i);
	}
	if(n==1){
		printf("%d\n",ksmii(2,a[1]));
		return 0;
	}
	int peak=1;
	for(int i=1;i<=n;i++){
		if(a[i]>a[i-1]&&a[i]>a[i+1]){
			peak=1LL*peak*ksmii(2,a[i]-max(a[i-1],a[i+1]))%Mod;
			a[i]=max(a[i-1],a[i+1]);
		}
	}
	pair<int,int> ans=solve(1,n,0);
	printf("%lld\n",1LL*peak*((ans.first+2LL*ans.second%Mod)%Mod)%Mod);
	return 0;
}